mapper.select:
select m.*, coalesce(sender.name, '系统通知') as sender_name, mine.read_at
from message m
left join member sender on sender.id=m.sender_member_id
left join message_recipient mine on mine.message_id=m.id and mine.recipient_member_id=#{memberId}
where

    mine.id is not null
    m.sender_member_id=#{memberId}
    (m.sender_member_id=#{memberId} or mine.id is not null)

and m.message_type = #{q.messageType}
and m.business_type = #{q.businessType}
and m.business_id = #{q.businessId}
and m.id=#{q.id}
and m.conversation_id=#{q.conversationId}
and m.sender_member_id=#{q.senderMemberId}
and exists(select 1 from message_recipient r where r.message_id=m.id and r.recipient_member_id=#{q.recipientMemberId})
and m.send_type=#{q.sendType}
and m.subject like concat('%',#{q.subject},'%')

    and mine.id is not null
    and mine.read_at is not nulland mine.read_at is null

and m.created_at >= #{q.createdFrom}
and m.created_at <= #{q.createdTo}
and m.sequence > #{q.afterSequence}
order by m.sequence ascorder by m.created_at desc,m.id desc
